import AppShell from "@/components/AppShell";import { db } from "@/lib/db";import { requireRoles } from "@/lib/auth";import { Role } from "@prisma/client";import { revalidatePath } from "next/cache";
export default async function Page(){const u=await requireRoles([Role.ADMIN]);const rows=await db.vendor.findMany({where:{tenantId:u.tenantId},orderBy:{name:"asc"}});async function save(fd:FormData){"use server";const a=await requireRoles([Role.ADMIN]);const id=String(fd.get("id")||"");const data={code:String(fd.get("code")).trim().toUpperCase(),name:String(fd.get("name")).trim(),taxId:String(fd.get("taxId")||"")||null,address:String(fd.get("address")||"")||null,bankName:String(fd.get("bankName")||"")||null,bankAccount:String(fd.get("bankAccount")||"")||null,bankAccountName:String(fd.get("bankAccountName")||"")||null,active:String(fd.get("active")||"true")==="true"};if(id)await db.vendor.updateMany({where:{id,tenantId:a.tenantId},data});else await db.vendor.create({data:{tenantId:a.tenantId,...data}});revalidatePath("/admin/vendors")}return <AppShell title="Vendors"><div className="card"><form action={save} className="form-grid"><input name="code" placeholder="VND001" required/><input name="name" placeholder="PT Vendor" required/><input name="taxId" placeholder="NPWP"/><input name="address" placeholder="Address"/><input name="bankName" placeholder="Bank"/><input name="bankAccount" placeholder="Account No"/><input name="bankAccountName" placeholder="Account Name"/><select name="active"><option value="true">Active</option><option value="false">Inactive</option></select><button className="btn">Add Vendor</button></form></div><div className="table-wrap section-title"><table><thead><tr><th>Code</th><th>Vendor</th><th>Tax ID</th><th>Bank</th><th>Status</th><th>Edit</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.code}</td><td>{r.name}</td><td>{r.taxId||"-"}</td><td>{r.bankName||"-"} {r.bankAccount||""}</td><td>{r.active?"Active":"Inactive"}</td><td><details><summary className="link">Edit</summary><form action={save} className="form-grid edit-grid"><input type="hidden" name="id" value={r.id}/><input name="code" defaultValue={r.code}/><input name="name" defaultValue={r.name}/><input name="taxId" defaultValue={r.taxId||""}/><input name="address" defaultValue={r.address||""}/><input name="bankName" defaultValue={r.bankName||""}/><input name="bankAccount" defaultValue={r.bankAccount||""}/><input name="bankAccountName" defaultValue={r.bankAccountName||""}/><select name="active" defaultValue={String(r.active)}><option value="true">Active</option><option value="false">Inactive</option></select><button className="btn secondary">Save</button></form></details></td></tr>)}</tbody></table></div></AppShell>}
